	if err != nil {
		return api.TrailCreateResponse{}, fmt.Errorf("failed to create trail: %w", err)
	}
	defer resp.Body.Close()
	if err := checkTrailResponse(resp); err != nil {
		return api.TrailCreateResponse{}, err
	}

